def logo_linguagem(chave, altura=16):
    if chave == 'ts':
        return (f'<svg viewBox="0 0 128 128" width="{altura}" height="{altura}" aria-hidden="true" style="display:block;flex:0 0 auto;">'
                f'<path fill="#fff" d="{_TS_FUNDO}"/><path fill="#3178C6" d="{_TS}"/></svg>')
    if chave == 'py':
        return (f'<svg viewBox="0 0 128 128" width="{altura}" height="{altura}" aria-hidden="true" style="display:block;flex:0 0 auto;">'
                f'<path fill="#3776AB" d="{_PY_AZUL}" transform="translate(0 10.26)"/>'
                f'<path fill="#FFD43B" d="{_PY_AMARELA}" transform="translate(0 10.26)"/></svg>')
    # o logotipo do Go é largo: a altura manda, a largura acompanha a proporção do recorte
    largura = round(altura * 24.2 / 9.4)
    return (f'<svg viewBox="0 7.3 24.2 9.4" width="{largura}" height="{altura}" aria-hidden="true" style="display:block;flex:0 0 auto;">'
            f'<path fill="#00ADD8" d="{_GO}"/></svg>')
